import { init, start } from "simplicit";

import Admin from "controllers/Admin";
import Main from "controllers/Main";
import User from "controllers/User";

import Article from "models/Article";
import Comment from "models/article/Comment";
import UserModel from "models/User";
import LoadMore from "components/main/LoadMore";

const Controllers = {
  Admin,
  Main,
  User,
};

// Scripts are loaded from <head> without `defer`, so <body> — and the
// data-model payload — do not exist yet at module eval.
document.addEventListener("DOMContentLoaded", () => {
  start({
    root: document,
    models: [Article, Comment, UserModel],
    components: [LoadMore],
  });
});

let env = null;

// Live updates belong to the page you are on. While a Turbo visit is in
// flight the incoming page has not hydrated yet, and its server snapshot can
// predate the update — Model.load would then replace the record away. So hold
// calls for the duration of a visit and run them once the new page has
// hydrated: a tick after turbo:load, since Simplicit hydrates from a
// MutationObserver callback.
// ponytail: `visiting` clears on turbo:load only. A visit whose response is
// prevented (a turbo-stream, or preventDefault on turbo:before-fetch-response)
// never fires it, and held calls would stall for good. Neither happens here.
let visiting = false;
const held = [];

document.addEventListener("turbo:visit", () => {
  visiting = true;
});

document.addEventListener("turbo:load", () => {
  env = init(Controllers);
  visiting = false;
  const queued = held.splice(0);
  if (queued.length > 0) setTimeout(() => queued.forEach((run) => run()), 0);
});

export const afterHydration =
  (fn) =>
  (...args) =>
    visiting ? held.push(() => fn(...args)) : fn(...args);

["turbo:click", "turbo:submit-start"].forEach((event) => {
  document.addEventListener(event, () => {
    if (env?.controller?.cleanup != null) {
      env.controller.cleanup();
      env.controller.cleanup = null;
    }
  });
});

const getEnv = () => env;

export default getEnv;
